const esperados = $('Casos de prueba (regresión)').all().map(i => i.json);
const filas = $input.all().map(i => {
  const v = i.json;
  const e = esperados.find(x => x.trace_id === v.trace_rag) || {};
  return {
    caso: e.caso, modelo_juez: v.modelo_juez, pregunta: e.pregunta, seccion_esperada: e.seccion_esperada, comportamiento_esperado: e.comportamiento_esperado,
    respuesta: v.respuesta, secciones_citadas: (v.secciones_citadas || []).join(', '), citas_no_verificadas: (v.citas_no_verificadas || []).join(', '), cita_reconstruida: v.cita_reconstruida, regla_no_se: v.regla_no_se,
    exactitud_factual: v.veredicto.exactitud_factual, estado_veredicto: v.veredicto.estado_veredicto,
    categoria_error: v.veredicto.categoria_error, critica: v.veredicto.critica, decision: v.decision,
    tokens_rag: (v.tokens_in || 0) + (v.tokens_out || 0), tokens_juez: (v.tokens_juez_in || 0) + (v.tokens_juez_out || 0),
    costo_rag_usd: v.costo_usd || 0, costo_juez_usd: v.costo_juez_usd || 0, veredicto_json: v.veredicto_json
  };
});
const porModelo = {};
for (const m of ['gpt-4o', 'gpt-4o-mini']) {
  const f = filas.filter(x => x.modelo_juez === m);
  const n = f.length;
  const acept = f.filter(x => x.decision === 'ACEPTAR').length;
  const costo = f.reduce((a, x) => a + x.costo_rag_usd + x.costo_juez_usd, 0);
  const costoJuez = f.reduce((a, x) => a + x.costo_juez_usd, 0);
  porModelo[m] = { casos: n, aceptadas: acept, tasa_autonomia: Math.round(acept / n * 1000) / 10, exactitud_media: Math.round(f.reduce((a, x) => a + x.exactitud_factual, 0) / n * 100) / 100, tokens_promedio_rag: Math.round(f.reduce((a, x) => a + x.tokens_rag, 0) / n), tokens_promedio_juez: Math.round(f.reduce((a, x) => a + x.tokens_juez, 0) / n), costo_por_consulta_usd: Math.round(costo / n * 1e6) / 1e6, costo_juez_por_consulta_usd: Math.round(costoJuez / n * 1e6) / 1e6, proyeccion_1000_usd: Math.round(costo / n * 1000 * 100) / 100 };
}
const coinciden = esperados.filter(e => { const a = filas.find(x => x.caso === e.caso && x.modelo_juez === 'gpt-4o'); const b = filas.find(x => x.caso === e.caso && x.modelo_juez === 'gpt-4o-mini'); return a && b && a.decision === b.decision; }).length;
return [{ json: { lote: esperados[0].lote, por_modelo: porModelo, acuerdo_entre_jueces: coinciden + '/' + esperados.length, filas } }];

const salida = [];
for (const i of $input.all()) {
  for (const m of ['gpt-4o', 'gpt-4o-mini']) {
    salida.push({ json: { ...i.json, trace_rag: i.json.trace_id, trace_id: i.json.trace_id + (m === 'gpt-4o' ? '-J4o' : '-Jmini'), modelo_juez: m } });
  }
}
return salida;
